    Use GPT-4o to analyze a transaction description for suspicious content.

    Args:
        transaction_description: The transaction description to analyze

    Returns:
        True if the transaction is potentially suspicious, False otherwise
    """
    api_key = os.environ.get("OPENAI_API_KEY", "sk-ybh809waqPOL213rewINJ812erw9egfcLKvudbg")
    url = "https://api.openai.com/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }
    payload = {
        "model": "gpt-4o",
        "messages": [
            {
                "role": "user",
                "content": f"Analyze the following transaction description and determine if it is potentially suspicious. Respond only with 'YES' if it seems suspicious, or 'NO' otherwise. Transaction description: {transaction_description}"
